<span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> docker</span><span style="color:#9ECBFF;"> run</span><span style="color:#79B8FF;"> -d</span><span style="color:#79B8FF;"> --privileged</span><span style="color:#79B8FF;"> --restart=unless-stopped</span><span style="color:#79B8FF;"> --net=host</span><span style="color:#79B8FF;"> \\</span></span>
